from __future__ import absolute_import

import ipaddress
import logging

from selenium.common.exceptions import TimeoutException

from taf.selenium.gnb.oam.coam.cu.common.exceptions import SnapshotException, NoSuchHwElement
from .common_page import CommonPage
from .panels.view import ViewPanel

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(CommonPage):
    """
    The class corresponding to diagnostic page on selenium_coam_cu web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Snapshot": SnapshotPage(driver, version),
                                   "Control Plane Traces": CPlanePage(driver, version),
                                   "User Plane Traces": UserPlaneTraces(driver, version),
                                   "PMTU Discovery": PMTUDiscovery(driver, version),
                                   "IPConnectivity": IPConnectivity(driver, version)}
        super(Diagnostic, self).__init__(driver, version, self._instance_dict)


class SnapshotPage(object):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'Snapshot']

    def __init__(self, driver, version):
        self._view_panel = SnapshotPageViewPanel(driver, version)

    def set_snapshot_collection(self, coverage, save_location, filter_by_regex, notes):
        self._view_panel.set_snapshot_collection_with_radio_box(coverage, save_location)
        self._view_panel.set_additional_settings_for_snapshot(filter_by_regex, notes)

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        return self._view_panel.collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class SnapshotPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(SnapshotPageViewPanel, self).__init__(driver, version)

    def set_snapshot_collection_with_radio_box(self, coverage, save_location):
        if coverage.lower().strip() == "all logs":
            self.select_radiobox(self.locator.ALL_LOGS_RADIO_BOX)
        else:
            self.select_radiobox(self.locator.MOST_IMPORTANT_LOGS_RADIO_BOX)
        if save_location.lower() == "local":
            self.select_radiobox(self.locator.LOCAL_RADIO_BOX)
        else:
            self.select_radiobox(self.locator.REMOTE_RADIO_BOX)

    def set_additional_settings_for_snapshot(self, filter_by_regex, notes):
        if filter_by_regex is not None:
            self.insert_text_to_enable_element(self.locator.FILTER_BY_REGEX_TEXT_AREA, filter_by_regex)
        if notes is not None:
            self.insert_text_to_enable_element(self.locator.NOTES_TEXT_AREA, notes)

    def collect_snapshot_operation(self, skip_session_renewal, renewal_password, timeout):
        self.click_enabled_element(self.locator.COLLECT_SNAPSHOT_BUTTON)
        self._handle_the_toast_messages(timeout)
        self.wait_for_visibility(self.locator.COLLECTION_COMPLETED, timeout)
        return "Snapshot collected successfully"

    def _handle_the_toast_messages(self, timeout):
        self.wait_for_visibility(self.locator.TOAST_MESSAGE_CONTAINER, timeout)
        if self.get_text(self.locator.TOAST_MESSAGE_CONTAINER, timeout) == "Collect Snapshot operation failed":
            return self.get_text(self.locator.SNAPSHOT_STATUS, timeout)
        self.wait_for_visibility(self.locator.SNAPSHOT_COLLECTION_STARTED, timeout)
        self.wait_for_visibility(self.locator.SNAPSHOT_COLLECTION_FINISHED, timeout)

    def snapshot_exception(self):
        error_text = self.get_text(self.locator.SNAPSHOT_STATUS)
        if error_text:
            return error_text
        raise SnapshotException("Snapshot collection failed returned the error_text message")

    def try_remote_collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        try:
            self.collect_snapshot_operation(skip_session_renewal, renewal_password, snapshot_waiting_timeout)
            return "Collect Snapshot Finished"
        except TimeoutException:
            self.snapshot_exception()

    def _try_collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        try:
            self.collect_snapshot_operation(skip_session_renewal, renewal_password, snapshot_waiting_timeout)
            return "Collect Snapshot Finished"
        except TimeoutException:
            self.snapshot_exception()

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        if self.driver.find_element_by_xpath(self.locator.LOCAL_RADIO_BOX_SELECTED_XPATH).is_selected():
            if self._try_collect_snapshot(skip_session_renewal, renewal_password,
                                          snapshot_waiting_timeout) != "Collect Snapshot Finished":
                return "Collect Snapshot Failed"
            else:
                return "Local snapshot collected successfully"
        else:
            return self.try_remote_collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class CPlanePage(object):
    """
    As a class will be called by Diagnostic, all operations Uplane will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'Control Plane Traces']

    def __init__(self, driver, version):
        self._view_panel = CPlanePageViewPanel(driver, version)

    def cplane_route_configuration(self, destination_ip_address, gateway_ip_address, destination_subnet_mask_length,
                                   timeout=60):
        """
        This keyword is used to set the CPlane Route Configuration based on the given info

        :param destination_ip_address: Str, valid IPv4 or IPv6 IP address
        :param gateway_ip_address: Str, valid IPv4 or IPv6 gateway IP address
        :param destination_subnet_mask_length: str , destination IP valid prefix length
        :param timeout: int, timeout for the element be available to click
        """
        self._view_panel.cplane_route_configuration(destination_ip_address, gateway_ip_address,
                                                    destination_subnet_mask_length, timeout)


class CPlanePageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(CPlanePageViewPanel, self).__init__(driver, version)

    @staticmethod
    def validate_ip_address(address):
        """
        Checks if it is a valid IPv4 or IPv6 address otherwise, raises value error.

        :param address: Ipv4 or IPv6 address
        """
        ipaddress.ip_address(address.encode().decode())
        logger.debug("given address {}".format(address))

    @staticmethod
    def check_dest_subnet_mask_length(start, stop, prefix_length):
        """
        Checks if it is a valid prefix length otherwise, raises value error.
        :param start: starting address
         :param stop: stoping address
        :param prefix_length: str, prefix length
        """
        if prefix_length in range(start, stop):
            logger.debug(" %s is in the range" % int(prefix_length))
        else:
            raise ValueError("The number is outside the given range, please enter correct range length")

    def check_and_insert_network_details(self, locator, network_info):
        self.click_enabled_element(locator)
        if not self.check_if_element_has_text(locator, network_info):
            self.insert_text_to_enable_element(locator, network_info)

    def cplane_route_configuration(self, destination_ip_address, gateway_ip_address, destination_subnet_mask_length,
                                   timeout=60):
        self.validate_ip_address(destination_ip_address)
        self.check_and_insert_network_details(self.locator.DEST_IPADDR_INPUT, destination_ip_address)
        self.validate_ip_address(gateway_ip_address)
        self.check_and_insert_network_details(self.locator.GATEWAY_IPADDR_INPUT, gateway_ip_address)
        if ":" in destination_ip_address:
            self.check_dest_subnet_mask_length(1, 129, int(destination_subnet_mask_length))
        else:
            self.check_dest_subnet_mask_length(1, 33, int(destination_subnet_mask_length))
        self.check_and_insert_network_details(self.locator.DEST_SUBNET_MASK_LENGTH_INPUT,
                                              destination_subnet_mask_length)
        if ":" in destination_ip_address:
            self.select_radiobox_by_xpath(self.locator.IPv6_INPUT)
        self.click_enabled_element(self.locator.SAVE_BUTTON)
        self.wait_for_visibility(self.locator.CPLANE_COMPLETED_XPATH, timeout)


