class UserPlaneTracesViewPanel(ViewPanel):
    def __init__(self, driver, version):
        self.driver = driver
        super(UserPlaneTracesViewPanel, self).__init__(driver, version)

    def user_plane_traces_destination_server_configuration(self, ip_address, port, dscp, timeout):
        """
        This keyword will update the destination server details for user plane trace
        :param ip_address: str, destination server ip address
        :param port: str, destination server port
        :param dscp: str, destination server dscp
        :param timeout: int, timeout for the element be available to click

        :return: return the status message of the upgrade.
        """
        self.click_enabled_element(self.locator.USER_PLANE_DESTINATION_IP_ADDRESS, timeout)
        self.insert_text_to_enable_element(self.locator.USER_PLANE_DESTINATION_IP_ADDRESS, ip_address, timeout)
        self.insert_text_to_enable_element(self.locator.DESTINATION_PORT, port, timeout)
        self.insert_text_to_enable_element(self.locator.USER_PLANE_DSCP_CONFIGURATION, dscp, timeout)
        self.click_enabled_element(self.locator.UPDATE_CONFIGURATION_BUTTON, timeout)
        self.wait_for_visibility(self.locator.TOAST_TITLE.format("Destination Server Configuration"))
        return self.get_text(self.locator.TOAST_MESSAGE_CONTAINER, timeout)

    def start_user_plane_traces(self, trace_type, timeout):
        """
        This keyword will start the user plane trace for the given trace type

        :param trace_type: Str, trace type to be took the trace
        :param timeout: int, timeout for the element be available to click

        """
        self.select_radiobox(self.locator.USER_PLANE_TRACE_TYPE_RADIO_BUTTON.format(trace_type.capitalize()), timeout)
        self.click_enabled_element(self.locator.START_USER_PLANE_TRACE_BUTTON, timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("Trace streams operation finished"))

    def stop_user_plane_traces(self, trace_type, timeout):
        """
        This keyword will stop the user plane trace for the given trace type
        :param trace_type: Str, trace type to be took the trace
        :param timeout: int, timeout for the element be available to click

        """
        self.click_enabled_element(self.locator.STOP_USER_PLANE_LOG_BUTTON.format(trace_type.capitalize()), timeout)
        self.wait_for_visibility(self.locator.TOAST_TITLE.format("Trace Stream stopped"), timeout)
        self.wait_for_visibility(self.locator.STOP_USER_PLANE_LOG_STATUS.format(trace_type.capitalize()), timeout)

    def restore_user_plane_traces_server_configuration(self, timeout):
        """
        This keyword will restore the server configuration to default configuration

        :param timeout: int, timeout for the element be available to click

        """
        self.click_enabled_element(self.locator.RESTORE_DEFAULTS_BUTTON, timeout)

    def delete_user_plane_traces(self, trace_type, timeout):
        """"
        This keyword will delete the user plane trace for the given trace type

        :param trace_type: Str, trace type to be took the trace
        :param timeout: int, timeout for the element be available to click
        """
        self.click_enabled_element(self.locator.DELETE_USER_PLANE_LOG_BUTTON.format(trace_type.capitalize()),
                                   timeout)
        self.wait_for_invisibility(self.locator.USER_PLANE_TABEL_ROW.format(trace_type.capitalize()), timeout)

    def get_ongoing_traces(self, timeout):
        """
        This keyword will return all the trace present the user plane traces
        :param timeout: int, timeout for the element be available to click

        :return: dict, user plane traces result
        """
        table_body = []
        header = self.get_fields_info_from_row("//p-table//thead//th", timeout)
        table_rows = self.get_all_matching_elements("//p-table//tbody//tr")
        for row in range(1, len(table_rows) + 1):
            table_body.append(self.get_fields_info_from_row("//p-table//tbody//tr[{}]//td".format(row), timeout))
        return self.zip_table_result(header, table_body)

    @staticmethod
    def zip_table_result(header, table_body):
        final_result = []
        for row in range(0, len(table_body)):
            final_result.append({(zip(header, table_body[row]))})
        return final_result


